const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
// The introduction is a real video. Other previews are labeled motion concepts.
const showroom=document.querySelector('#hero-screen'),showTabs=[...document.querySelectorAll('[data-show]')],motionButton=document.querySelector('#gallery-motion');let selectedShow='intro',showPaused=motionPreference.matches;
const pic=(id,w=700)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const media={product:'photo-1542291026-7eec264c27ff',story:'photo-1464822759023-fed622ff2c3b',person:'photo-1534528741775-53994a69daeb'};
