function syncGalleryMotion(){showroom.classList.toggle('show-paused',showPaused);motionButton.hidden=selectedShow==='intro';motionButton.textContent=showPaused?'▶ Play':'Ⅱ Pause';motionButton.setAttribute('aria-label',showPaused?'Play preview animation':'Pause preview animation')}
function selectShow(name){selectedShow=name;showTabs.forEach(b=>{let on=b.dataset.show===name;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});showroom.setAttribute('aria-labelledby','show-'+name);showroom.dataset.show=name;document.querySelector('#gallery-title').textContent=showData[name].title;document.querySelector('#gallery-subtitle').textContent=showData[name].sub;document.querySelector('#gallery-count').textContent=String(Object.keys(showData).indexOf(name)+1).padStart(2,'0')+' / 06';
if(name==='intro'){showroom.innerHTML=`<button class="intro-cover" aria-label="Play official FilmWizard introduction"><img src="https://cdn.loom.com/sessions/thumbnails/a5f75b4b78f8497ab40e7bd4de80740c-a3e4ea555eed7df0.gif" alt="FilmWizard official introduction preview"><span class="cover-top">✦ FILMWIZARD</span><span class="big-play">▶</span><span class="cover-bottom"><strong>See FilmWizard in action.</strong><small>OFFICIAL INTRODUCTION &nbsp; 1:34</small></span></button>`;showroom.querySelector('button').addEventListener('click',()=>{showroom.innerHTML='<iframe src="https://www.loom.com/embed/a5f75b4b78f8497ab40e7bd4de80740c?autoplay=1&hide_owner=true&hide_share=true" title="FilmWizard official introduction" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe>'})}
if(name==='examples'){showroom.innerHTML=`<div class="show-scene example-scene"><span class="scene-eyebrow">YOUR NEXT CREATIVE DIRECTION</span><div class="example-fan">${['product','story','person'].map((k,i)=>`<div><img src="${pic(media[k])}" alt="Illustrative ${k} concept"><span>${['PRODUCT REVEAL','STORYTELLING','AI CHARACTER'][i]}</span></div>`).join('')}</div><strong class="scene-bottom-title">One brand. Endless possibilities.</strong><span class="scene-disclosure">VISUAL CONCEPTS</span></div>`}
if(name==='remix'){showroom.innerHTML='<div class="show-scene remix-scene"><span class="scene-eyebrow">CONTENT REMIXER</span><div class="remix-large"><div class="reference-large"><small>YOUR REFERENCE</small><span>▶</span><strong>A great hook.</strong></div><div class="remix-bridge"><span>↻</span><small>REMIX</small></div><div class="reference-large branded"><small>YOUR BRAND</small><span>✦</span><strong>Your own story.</strong></div></div><div class="link-prompt">↗ Paste a reference. Make it yours.</div><span class="scene-disclosure">ILLUSTRATIVE WORKFLOW</span></div>'}
if(name==='formats'){showroom.innerHTML='<div class="show-scene formats-scene"><span class="scene-eyebrow">THE TEMPLATE COLLECTION</span><div class="formats-number">100<span>PROVEN FORMATS</span></div><div class="formats-orbit"><span>Product reveals ↗</span><span>Storytelling ↗</span><span>Educational hooks ↗</span><span>Before & after ↗</span><span>Skits ↗</span><span>Creative remixes ↗</span></div><span class="scene-disclosure">ILLUSTRATIVE COLLECTION</span></div>'}
if(name==='carousel'){showroom.innerHTML='<div class="show-scene carousel-scene"><span class="scene-eyebrow">CAROUSEL AUTOMATION</span><div class="show-carousel"><div><small>YOUR BRAND / 01</small><strong>Start with<br>a great<br>idea.</strong><b>✦</b></div><div><small>YOUR BRAND / 02</small><strong>Make it<br>worth<br>the swipe.</strong><b>↗</b></div><div><small>YOUR BRAND / 03</small><strong>Give them<br>something<br>to save.</strong><b>⊞</b></div></div><span class="scene-disclosure">ILLUSTRATIVE WORKFLOW</span></div>'}
if(name==='avatar'){showroom.innerHTML=`<div class="show-scene avatar-scene"><span class="scene-eyebrow">YOUR AI CONTENT MACHINE</span><div class="avatar-machine"><div class="machine-person"><img src="${pic(media.person)}" alt="Illustrative avatar concept"><span>YOUR CHARACTER</span></div><div class="machine-connector">✦</div><div class="machine-output"><span>01 &nbsp; Product story ↗</span><span>02 &nbsp; Educational hook ↗</span><span>03 &nbsp; Brand update ↗</span><span>04 &nbsp; Your next idea ↗</span></div></div><strong class="scene-bottom-title">Same character. Fresh content.</strong><span class="scene-disclosure">ILLUSTRATIVE WORKFLOW</span></div>`}syncGalleryMotion()}
showTabs.forEach((b,i)=>{b.addEventListener('click',()=>selectShow(b.dataset.show));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%showTabs.length;if(e.key==='ArrowLeft')n=(i+showTabs.length-1)%showTabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=showTabs.length-1;if(n!==undefined){e.preventDefault();showTabs[n].focus();selectShow(showTabs[n].dataset.show)}})});motionButton.addEventListener('click',()=>{showPaused=!showPaused;syncGalleryMotion()});motionPreference.addEventListener('change',()=>{showPaused=motionPreference.matches;syncGalleryMotion()});selectShow('intro');
// Scroll reveals and card motion only run when visible; reduced motion stays static.
const reveals=[...document.querySelectorAll('.reveal')];if('IntersectionObserver'in window){document.documentElement.classList.add('reveal-enabled');const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');revealObserver.unobserve(e.target)}}),{threshold:.12});reveals.forEach(e=>revealObserver.observe(e));const motionObserver=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('motion-visible',e.isIntersecting)),{threshold:.2});document.querySelectorAll('.workflow-card').forEach(e=>motionObserver.observe(e));const showObserver=new IntersectionObserver(e=>showroom.classList.toggle('offscreen',!e[0].isIntersecting),{threshold:.1});showObserver.observe(showroom)}
let scrollQueued=false;function updateScrollArt(){scrollQueued=false;if(motionPreference.matches)return;const r=document.querySelector('.content-workflows').getBoundingClientRect();const p=Math.max(0,Math.min(1,(innerHeight-r.top)/(innerHeight+r.height)));document.querySelector('.content-workflows').style.setProperty('--scroll-flow',p.toFixed(3))}addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateScrollArt)}},{passive:true});updateScrollArt();
// Website player drives the paused, seekable HyperFrames compositions.
const motionPlayers=[...document.querySelectorAll('[data-hf]')].map(w=>({wrap:w,frame:w.querySelector('iframe'),id:w.dataset.hf,duration:Number(w.dataset.duration),t:motionPreference.matches?(w.dataset.hf==='studio'?22:5):0,playing:!motionPreference.matches,visible:false,timeline:null}));
const mainPlayer=motionPlayers.find(p=>p.id==='studio');const chapterButtons=[...document.querySelectorAll('[data-seek]')];
function paintMotion(p){if(!p.timeline)return;p.timeline.totalTime(p.t,false);if(p===mainPlayer){const chapter=p.t<2.7?0:p.t<5?1:p.t<8.5?2:p.t<11.6?3:p.t<17?4:5;chapterButtons.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===chapter));b.tabIndex=i===chapter?0:-1})}}
function syncMotionButton(){const b=document.querySelector('#motion-toggle');b.textContent=mainPlayer.playing?'Ⅱ Pause':'▶ Play';b.setAttribute('aria-label',mainPlayer.playing?'Pause workflow':'Play workflow')}
motionPlayers.forEach(p=>{const size=p.id==='studio'?1200:400;new ResizeObserver(()=>{p.frame.style.transform=`scale(${p.wrap.clientWidth/size})`}).observe(p.wrap);p.frame.addEventListener('load',()=>{try{p.timeline=p.frame.contentWindow.__timelines?.[p.id];paintMotion(p)}catch(e){p.wrap.dataset.error='Preview unavailable'}});new IntersectionObserver(e=>{p.visible=e[0].isIntersecting},{threshold:.25}).observe(p.wrap)});
let motionLast=0;function motionTick(now){const dt=motionLast?Math.min((now-motionLast)/1000,.1):0;motionLast=now;motionPlayers.forEach(p=>{if(p.playing&&p.visible&&!document.hidden){p.t=(p.t+dt)%p.duration;paintMotion(p)}});requestAnimationFrame(motionTick)}requestAnimationFrame(motionTick);
document.querySelector('#motion-toggle').addEventListener('click',()=>{mainPlayer.playing=!mainPlayer.playing;syncMotionButton()});document.querySelector('#motion-replay').addEventListener('click',()=>{mainPlayer.t=0;mainPlayer.playing=true;paintMotion(mainPlayer);syncMotionButton()});chapterButtons.forEach((b,i)=>{function pick(){mainPlayer.t=Number(b.dataset.seek);mainPlayer.playing=false;paintMotion(mainPlayer);syncMotionButton()}b.addEventListener('click',pick);b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%chapterButtons.length;if(e.key==='ArrowLeft')n=(i+chapterButtons.length-1)%chapterButtons.length;if(n!==undefined){e.preventDefault();chapterButtons[n].focus();chapterButtons[n].click()}})});motionPreference.addEventListener('change',()=>{motionPlayers.forEach(p=>{p.playing=!motionPreference.matches;if(motionPreference.matches)p.t=p.id==='studio'?22:5;paintMotion(p)});syncMotionButton()});syncMotionButton();
// Count up to observed public view snapshots; never imply live analytics.
const countObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target,target=Number(el.dataset.viewCount);countObserver.unobserve(el);if(motionPreference.matches)return;let start;function frame(t){start??=t;const p=Math.min(1,(t-start)/1900),value=target*(1-Math.pow(1-p,3));el.textContent=(value/1e6).toFixed(1)+'M';if(p<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)}),{threshold:.6});document.querySelectorAll('[data-view-count]').forEach(el=>countObserver.observe(el));

document.querySelectorAll('.mini-embed').forEach(w=>new ResizeObserver(()=>{w.querySelector('iframe').style.transform=`scale(${w.clientWidth/326})`}).observe(w));
